 "content": "def transform(grid):
    """Project shared top/bottom marker columns down to the first full-row barrier."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if h < 3:
        return out

    # Locate a uniform, nonzero horizontal separator below the top marker row.
    barrier = next(
        (r for r in range(1, h - 1)
         if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])),
        None,
    )
    if barrier is None:
        return out

    top = grid[0]
    bottom = grid[-1]
    for c in range(w):
        color = top[c]
        if color != 0 and bottom[c] == color:
            for r in range(1, barrier):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out
